// Redesigned StudentDashboard Component with Sidebar and Improved Layout
//import React from "react";
import "./StudentDashboard.css"; // Corresponding CSS file for the theme
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import StudentSidebar from "../components/StudentSidebar";




const StudentDashboard = () => {

    const handleLogout = () => {
        console.log("Logging out...");
        navigate("/"); // Redirect to the homepage
    };

    const [isModalOpen, setIsModalOpen] = useState(false);
    const navigate = useNavigate();

    const openLogoutModal = () => setIsModalOpen(true);
    const closeLogoutModal = () => setIsModalOpen(false);

    const confirmLogout = () => {
        // Clear any session or local storage data (optional)
        console.log("Logging out...");
        navigate("/"); // Redirect to the homepage
      };

  const announcements = [
    { id: 1, text: "Mid-term evaluation results have been published." },
    { id: 2, text: "Next project milestone due: March 10th." },
    { id: 3, text: "Reminder: Group meeting scheduled for tomorrow." },
  ];

 /*  const features = [
    { id: 1, name: "View and Manage Deadlines", icon: "fas fa-calendar-alt" },
    { id: 2, name: "View Assigned Tasks and Milestones", icon: "fas fa-tasks" },
    { id: 3, name: "Submit Proposals", icon: "fas fa-file-upload" },
    { id: 4, name: "Access Team Chat and Video Conferencing", icon: "fas fa-comments" },
    { id: 5, name: "Upload Documents", icon: "fas fa-upload" },
    { id: 6, name: "Provide Feedback", icon: "fas fa-comment-dots" },
    { id: 7, name: "View FYP Recommendations", icon: "fas fa-lightbulb" },
    { id: 8, name: "View Successful FYPs", icon: "fas fa-trophy" },
    { id: 9, name: "Access Communication Tools", icon: "fas fa-envelope" },
    { id: 10, name: "Search Documents", icon: "fas fa-search" },
    { id: 11, name: "View Notifications", icon: "fas fa-bell" },
    { id: 12, name: "Logout", icon: "fas fa-sign-out-alt" },
  ]; */

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="dashboard-layout">

      <StudentSidebar onLogout={openLogoutModal} />
       


        

        {/* Main Content */}
        <main className="dashboard-main">
          <div className="hero-section">
            <h1>Welcome, [Student Name]!</h1>
            <p>Track your progress and stay updated with the latest announcements.</p>
          </div>

          <div className="dashboard-content">
            <div className="dashboard-section">
              <h2>Your Tasks</h2>
              <div className="card-grid">
                <div className="dashboard-card">
                  <i className="fas fa-tasks"></i>
                  <h3>Pending Tasks</h3>
                  <p>Complete documentation for the second milestone.</p>
                </div>
                <div className="dashboard-card">
                  <i className="fas fa-check-circle"></i>
                  <h3>Completed Tasks</h3>
                  <p>Proposal submission successfully reviewed.</p>
                </div>
              </div>
            </div>

            <div className="dashboard-section">
              <h2>Announcements</h2>
              <ul className="announcement-list">
                {announcements.map((announcement) => (
                  <li key={announcement.id}>{announcement.text}</li>
                ))}
              </ul>
            </div>

            <div className="dashboard-section">
              <h2>Progress Overview</h2>
              <div className="progress-card">
                <h3>Milestone 1</h3>
                <p>Completion: 80%</p>
                <div className="progress-bar">
                  <div className="progress" style={{ width: "80%" }}></div>
                </div>
              </div>
              <div className="progress-card">
                <h3>Milestone 2</h3>
                <p>Completion: 40%</p>
                <div className="progress-bar">
                  <div className="progress" style={{ width: "40%" }}></div>
                </div>
              </div>
            </div>
          </div>
        </main>
      </div>
      {isModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Are you sure you want to log out?</h3>
            <button className="btn-confirm" onClick={confirmLogout}>
              Yes
            </button>
            <button className="btn-cancel" onClick={closeLogoutModal}>
              No
            </button>
          </div>
        </div>
      )}
      <Footer />
    </div>
  );
};

export default StudentDashboard;
